SELECT name_de, id, energy_kcal_per_100g FROM ingredients WHERE source='USDA_FDC' AND (LOWER(name_de) LIKE '%brühe%' OR LOWER(name_de) LIKE '%beere%' OR LOWER(name_de) LIKE '%bouillon%' OR LOWER(name_de) LIKE '%fond%' OR LOWER(name_de) LIKE '%heidelbeere%' OR LOWER(name_de) LIKE '%himbeere%' OR LOWER(name_de) LIKE '%erdbeere%' OR LOWER(name_de) LIKE '%brombeere%') ORDER BY name_de;
